import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 64 · everyday recipe: Salisbury steak with mushroom onion gravy (Google Trends 3/11: dinner recipes; budget comfort food)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, in nineteen fifty-six, the most modern thing in our kitchen was the TV dinner. A little aluminum tray with three sections. Salisbury steak in gravy, mashed potatoes, and a little square of peas and carrots. My brother Danny thought it was the height of luxury. My mother tasted one bite and said, I can do better than that for half the price. And she did.""",
   "salisbury steak mushroom gravy plate", "I CAN DO BETTER")
sc("""Most people today only know Salisbury steak from that frozen tray, rubbery and gray in a salty brown sauce. So tonight I'm giving you my mother's homemade Salisbury steak, tender and juicy in a rich mushroom and onion gravy, every step, and the five mistakes that make it rubbery. And stay with me, because the last secret is the way to finish it, and it's the reason hers was so tender.""",
   "TV dinner tray 1950s", "RUBBERY AND GRAY")

ch("A doctor's steak")
sc("""Here's something most people don't know, honey. Salisbury steak was invented by a doctor. His name was James Salisbury, an American doctor in the eighteen hundreds, who believed people should eat chopped beef patties for their health. He prescribed it to soldiers in the Civil War. By the time I was a girl, it had turned into a ground beef patty in gravy, and nobody remembered the doctor.""",
   "Civil War era doctor portrait", "INVENTED BY A DOCTOR")
sc("""My mother made it every other Tuesday, with a pound and a half of hamburger, a few mushrooms, and an onion. It fed the four of us with leftovers for my father's lunch pail. She served it over mashed potatoes with a pile of green beans, and the gravy was so good, Danny would lick his plate when he thought she wasn't looking. She was always looking.""",
   "1950s family dinner table mashed potatoes", "SHE WAS ALWAYS LOOKING")
sc("""And today, a homemade Salisbury steak supper feeds four for about twelve dollars, and it's on the table in forty minutes. It's the kind of supper that makes a tired Tuesday feel like Sunday. In a minute I'll tell you the first mistake, and it's the meat you pick at the store.""",
   "weeknight family supper table", "TUESDAY FEELS LIKE SUNDAY")

ch("What you need")
sc("""Here's what you need, honey, for four big patties. One and a half pounds of ground beef. A third of a cup of plain bread crumbs, or crushed saltine crackers. One egg. Two tablespoons of ketchup. One tablespoon of Worcestershire sauce. One teaspoon of mustard. Half a small onion, grated. Salt and pepper. That's the patties.""",
   "ground beef breadcrumbs egg ketchup", "THE PATTIES")
sc("""For the gravy. Two tablespoons of butter. Eight ounces of mushrooms, sliced. One onion, sliced thin. Two tablespoons of flour. Two cups of beef broth. One tablespoon of Worcestershire. A teaspoon of tomato paste or ketchup. And a little fresh thyme, if you have it. My mother added a splash of strong black coffee from the pot. It sounds strange, but it makes the gravy dark and rich.""",
   "mushrooms onions beef broth", "A SPLASH OF COFFEE")
sc("""And here's mistake number one. Too lean meat. The extra-lean ground beef, ninety-three percent, makes dry, rubbery patties. Use eighty or eighty-five percent lean. The little bit of fat keeps the patties juicy and tender, and it gives you drippings to start the gravy. My mother bought whatever the butcher ground that morning, and it was never lean.""",
   "ground beef package 80 percent", "NOT TOO LEAN")

ch("The patties")
sc("""Step one. In a big bowl, mix the bread crumbs, the egg, ketchup, Worcestershire, mustard, grated onion, a teaspoon of salt and half a teaspoon of pepper. Then add the beef, and mix it gently with your fingertips, just until it's combined. Mistake number two is overmixing. Squeeze and knead it too much, and the patties turn dense and rubbery, like the TV dinner.""",
   "mixing ground beef gently fingertips", "MIX IT GENTLY")
sc("""Divide it into four equal parts, and shape each one into an oval patty, about three quarters of an inch thick. Make them a little thinner in the middle than at the edges, pressing a little dent in the center with your thumb. That way they cook evenly and don't puff up into a ball. Then set them on a plate and chill them fifteen minutes, so they hold together.""",
   "oval beef patties thumb dent", "A DENT IN THE MIDDLE")
sc("""If this is helping you, honey, tap the like button for me. It helps Grandma more than you know. Heat a big skillet over medium-high heat with a spoon of oil. Lay the patties in, and leave them alone for four minutes, until they have a deep brown crust. Then flip them and brown the other side, another three or four minutes. Then take them out onto a plate. They don't need to be cooked through yet.""",
   "browning patties skillet crust", "A DEEP BROWN CRUST")
sc("""Mistake number three is a pale patty. If you crowd the pan, or flip them too soon, or keep pushing them around, they steam and turn gray instead of brown. That brown crust is where the flavor is, and those brown bits left in the pan are the start of the gravy. Leave them alone, honey. Patience is an ingredient too.""",
   "gray steamed meat patties pan", "PATIENCE IS AN INGREDIENT")

sc("""And here's a trick for mushrooms, honey, that my mother learned from the grocer. Don't wash them under the faucet. They soak up water like a sponge, and then they steam in the pan instead of browning. Just wipe them clean with a damp paper towel. And slice them thick, about a quarter inch, so they stay meaty. Thin slices shrink into nothing.""",
   "wiping mushrooms paper towel", "DON'T WASH THEM")

ch("The gravy")
sc("""Step two, the gravy. Pour off all but about a tablespoon of fat from the pan. Add the butter, and then the mushrooms and sliced onion. Cook them over medium heat for about eight to ten minutes, stirring now and then, until the mushrooms are brown and the onions are soft and golden. Don't stir the mushrooms too much at first. Let them sit and brown.""",
   "mushrooms onions browning skillet", "LET THEM BROWN")
sc("""Sprinkle the flour over the mushrooms and onions, and stir for two minutes. Then slowly pour in the beef broth, stirring and scraping up all those brown bits from the bottom of the pan. Add the Worcestershire, the tomato paste, the thyme, and that splash of coffee. Let it bubble until it's thick, about three or four minutes. Taste it, and add salt and pepper.""",
   "pouring broth gravy skillet scraping", "SCRAPE THE BOTTOM")
sc("""Mistake number four is a thin, pale gravy. If the gravy is light and watery, it's because the mushrooms and onions weren't browned enough, or it didn't simmer long enough. Brown the vegetables well, and let the gravy reduce until it coats the back of a spoon. It should be the color of dark chocolate. That's what makes it taste like Sunday.""",
   "thick dark mushroom gravy spoon", "THE COLOR OF DARK CHOCOLATE")

ch("The secret finish")
sc("""So far, eighty-five percent beef, a gentle mix, a dent in the middle, a deep brown crust, and a dark mushroom gravy. And now the secret I promised, my mother's finish. Mistake number five is cooking the patties all the way through in the skillet, before the gravy. They dry out. Instead, put the browned patties back into the gravy, and spoon gravy over the top.""",
   "patties back in gravy skillet", "BACK INTO THE GRAVY")
sc("""Then turn the heat down to low, cover the skillet, and let them simmer gently in the gravy for about ten to twelve minutes, until they're cooked through, to one hundred sixty degrees in the middle. The patties soak up the gravy, and the gravy soaks up the beef. They come out so tender you can cut them with a fork. That's the reason my mother's beat the TV dinner every time.""",
   "simmering patties covered skillet", "TENDER AS A FORK")

sc("""And if you're making a big batch for company, sweetheart, put the browned patties in a baking dish, pour the gravy over them, cover it with foil, and bake it at three fifty for about twenty-five minutes. Then the stove is free for the potatoes and the beans. My mother made twelve of them that way for my father's bowling league banquet in nineteen fifty-eight. They asked her back every year.""",
   "baking dish patties gravy foil", "THE BOWLING LEAGUE")

ch("Serving")
sc("""Serve it the way my mother did, honey. A big scoop of mashed potatoes, a patty on top, and plenty of mushroom gravy poured over everything, with green beans or peas on the side. Or serve it over buttered egg noodles or rice. Sprinkle a little chopped parsley on top. And put the bread basket on the table for the gravy. Nobody leaves gravy on a plate in my house.""",
   "Salisbury steak mashed potatoes green beans", "NOBODY LEAVES GRAVY")
sc("""And the leftovers, sweetheart. Salisbury steak is even better the next day, warmed gently in its gravy. It keeps three days in the icebox. And it freezes beautifully, patties and gravy together, for three months. Make a double batch, and freeze half in containers. Then on a busy night, it's your own homemade TV dinner, and a whole lot better than the one in the tray.""",
   "frozen meals containers gravy", "YOUR OWN TV DINNER")
sc("""And you can make it fancy for company, honey. Add a splash of red wine or sherry to the gravy, and a spoon of sour cream at the end. Or make it with ground turkey for a lighter supper, with a little extra Worcestershire for flavor. My granddaughter makes it in her slow cooker, browned first, and then cooked on low in the gravy for four hours.""",
   "slow cooker salisbury steak", "FANCY FOR COMPANY")

ch("Grandma's kitchen")
sc("""So one more time. Eighty or eighty-five percent beef, never extra lean. Bread crumbs, egg, ketchup, Worcestershire and grated onion. Mix it gently. Oval patties with a dent in the middle. A deep brown crust. Mushrooms and onions browned well, and a dark gravy with a splash of coffee. Then simmer the patties in the gravy until they're fork tender. That's my mother's Salisbury steak.""",
   "Salisbury steak family supper", "FORK TENDER")
sc("""Tell me in the comments, sweetheart. Did you eat TV dinners growing up? Which one was your favorite? Mine was the turkey with the little apple cobbler. The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey.""",
   "1950s family TV dinner trays", "YOUR FAVORITE TV DINNER?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma64", "Salisbury Steak EVERYONE's Grandma Made (Why Yours Is RUBBERY)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Salisbury steak, named for Dr. James H. Salisbury (1823-1905), and the frozen TV dinners of the 1950s.",
      "Food safety: cook ground beef to 160 F (USDA Food Safety and Inspection Service).",
      "Recipe as written by Grandma Ruth: 1 1/2 lb 80 to 85 percent lean ground beef, 1/3 cup bread crumbs, 1 egg, 2 tbsp ketchup, 1 tbsp Worcestershire, 1 tsp mustard, grated onion; gravy of 8 oz mushrooms, 1 onion, 2 tbsp butter, 2 tbsp flour, 2 cups beef broth, Worcestershire, tomato paste, thyme and a splash of coffee."],
     "everyday recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
